import { describe, test, expect, beforeAll } from 'bun:test'
import app from './src/app.js'
import { TestApp } from '@guren/testing'
import { Post } from './app/Models/Post.js'
import { Tag } from './app/Models/Tag.js'
import { PostTag } from './app/Models/PostTag.js'

describe('Tags Feature', () => {
  let http: TestApp
  let userId: number

  beforeAll(async () => {
    http = await TestApp.fromApp(app)

    // Create a test user
    const { User } = await import('./app/Models/User.js')
    const user = await User.create({
      name: 'Test User',
      email: `test-${Date.now()}@example.com`,
      password: 'password',
    })
    userId = user!.id!
  })

  test('create post with tags', async () => {
    const csrf = await http.actingAs({ id: userId } as any).withCsrf()

    const response = await csrf.post('/posts', {
      title: 'Test Post',
      excerpt: 'An excerpt',
      body: 'Body text',
      tags: 'bun, webdev',
    })

    expect(response.status).toBe(303)

    // Verify tags were created
    const tags = await Tag.all()
    expect(tags.length).toBeGreaterThanOrEqual(2)

    // Verify post_tags were created
    const postTags = await PostTag.all()
    expect(postTags.length).toBeGreaterThanOrEqual(2)
  })

  test('tags are returned in post data', async () => {
    const csrf = await http.actingAs({ id: userId } as any).withCsrf()

    const response = await csrf.post('/posts', {
      title: 'Another Post',
      excerpt: 'Excerpt',
      body: 'Body',
      tags: 'react, typescript',
    })

    // Get the post ID from redirect URL
    const location = response.headers.get('location')
    const postId = parseInt(location?.split('/').pop() || '0')

    // Check the post has tags
    const posts = await Post.newQuery().with('tags').get()
    const post = posts.find((p) => p.id === postId)
    expect(post).toBeDefined()
    expect((post as any).tags?.length).toBe(2)
  })

  test('filtering by tag works', async () => {
    const response = await http.get('/posts?tag=bun')
    expect(response.status).toBe(200)
  })
})
EOF
